export type IconName = keyof typeof ICONS;

interface IconProps {
  name: IconName;
  // 픽셀 크기. 생략하면 원본 크기(16/24/28/40)로 렌더한다.
  size?: number;
  className?: string;
  // 의미 있는 아이콘이면 라벨을 준다. 없으면 장식으로 보고 스크린리더에서 숨긴다.
  'aria-label'?: string;
}

export function Icon({
  name,
  size,
  className,
  'aria-label': ariaLabel,
}: IconProps) {
  const icon = ICONS[name];
  const s = size ?? icon.size;
  return (
    <svg
      viewBox={icon.box}
      width={s}
      height={s}
      fill="none"
      role={ariaLabel ? 'img' : undefined}
      aria-label={ariaLabel}
      aria-hidden={ariaLabel ? undefined : true}
      className={cn('inline-block shrink-0', className)}
    >
      {icon.body}
    </svg>
  );
}
